<!-- Rastreamento LED para mapa em tempo real -->
<script>
(async function() {
  const TRACK_ENDPOINT = 'https://app.rabbtifyecom.com/app/api/track_led_visitor.php'; // endpoint novo

  async function resolveSlug() {
    try {
      const response = await fetch('loja.json', { cache: 'no-store' });
      if (response.ok) {
        const loja = await response.json();
        const slug = String(loja?.slug || loja?.nome || '').trim();
        if (slug !== '') return slug;
      }
    } catch (e) {}
    const configuredSlug = String(window.LOJA_SLUG || '').trim();
    if (configuredSlug !== '') return configuredSlug;
    return (window.location.hostname || 'vitrine').trim();
  }

  const SLUG = await resolveSlug();

  async function getLocation() {
    // Primeiro tenta geolocalização do navegador
    let loc = await new Promise(resolve => {
      if (!navigator.geolocation) return resolve({});
      navigator.geolocation.getCurrentPosition(
        pos => resolve({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
        () => resolve({})
      );
    });
    return loc;
  }

  async function trackVisitor(stage) {
    const loc = await getLocation();
    const payload = {
      slug: SLUG,
      stage: stage || 'vitrine',
      lat: loc.lat,
      lng: loc.lng,
      url: window.location.href,
      ref: document.referrer || '',
      ua: navigator.userAgent
    };
    fetch(TRACK_ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
  }

  // Envia ao carregar a página
  trackVisitor('vitrine');
})();
</script>
<!-- Rastreamento de visitantes para mapa em tempo real -->
<script>

(async function() {
  // Configurações
  const TRACK_ENDPOINT = 'https://app.rabbtifyecom.com/app/api/track_visitor.php'; // endpoint real

  async function resolveSlug() {
    try {
      const response = await fetch('loja.json', { cache: 'no-store' });
      if (response.ok) {
        const loja = await response.json();
        const slug = String(loja?.slug || loja?.nome || '').trim();
        if (slug !== '') return slug;
      }
    } catch (e) {}
    const configuredSlug = String(window.LOJA_SLUG || '').trim();
    if (configuredSlug !== '') return configuredSlug;
    return (window.location.hostname || 'vitrine').trim();
  }

  const SLUG = await resolveSlug();

  // Função para obter localização (opcional)
  async function getLocation() {
    // Primeiro tenta geolocalização do navegador
    let loc = await new Promise(resolve => {
      if (!navigator.geolocation) return resolve({});
      navigator.geolocation.getCurrentPosition(
        pos => resolve({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
        () => resolve({})
      );
    });
    return loc;
  }

  // Função para enviar dados

  async function trackVisitor(stage) {
    const loc = await getLocation();
    const payload = {
      slug: SLUG,
      stage: stage || 'vitrine',
      lat: loc.lat,
      lng: loc.lng,
      url: window.location.href,
      ref: document.referrer || '',
      ua: navigator.userAgent
    };
    fetch(TRACK_ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
  }

  // Envia ao carregar a página
  trackVisitor('vitrine');

  // Exemplo: envie também ao entrar no checkout/pix
  // trackVisitor('checkout');
  // trackVisitor('pix');
})();
</script>
