<script>
function abrirModalCartinha() {
  document.getElementById('modalCartinha').style.display = 'flex';
}
function fecharModalCartinha() {
  document.getElementById('modalCartinha').style.display = 'none';
}
function resgatarCartinha() {
  fecharModalCartinha();
  // Aqui você pode aplicar cupom, redirecionar, etc.
}
// Timer regressivo (24h)
(function(){
  var total = 24*60*60; // 24 horas em segundos
  var el = document.getElementById('modalCartinhaCountdown');
  function tick() {
    if (total <= 0) return;
    var h = Math.floor(total/3600).toString().padStart(2,'0');
    var m = Math.floor((total%3600)/60).toString().padStart(2,'0');
    var s = (total%60).toString().padStart(2,'0');
    el.textContent = h+':'+m+':'+s;
    total--;
    setTimeout(tick,1000);
  }
  tick();
})();
// Exibe o modal automaticamente ao abrir a página (só uma vez por sessão)
(function(){
  if (!sessionStorage.getItem('modalCartinhaVisto')) {
    setTimeout(abrirModalCartinha, 600); // delay para UX
    sessionStorage.setItem('modalCartinhaVisto','1');
  }
})();
</script>
    <script>
