                    : `<button data-action="open-modal" data-index="${index}" style="background:#ffe0e6;border:none;border-radius:4px 0 0 4px;width:36px;height:30px;display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;"><img src="/uploads/carrinho-rosa.png?v=3" style="width:34px;height:34px;object-fit:contain;"></button><a href="${targetUrl}" data-produto-id="${pid}" class="produto-link" style="background:#fe2d55;color:#fff;border:none;border-radius:0 4px 4px 0;height:30px;padding:0 8px;font-size:13px;font-weight:500;letter-spacing:0px;cursor:pointer;white-space:nowrap;display:inline-flex;align-items:center;text-decoration:none;">Comprar</a>`
                  }
