    function restoreCatFromHash() {
      const hash = decodeURIComponent(location.hash || '');
      if (!hash.startsWith('#cat=')) return;
      const catId = hash.slice(5);
      const cat = categoriasList.find(c => c.id === catId);
      if (cat) openCatPanel(cat);
    }

    function renderCategoriasTab() {
      const catListEl = document.getElementById('catList');
      if (!catListEl) return;
      if (!categoriasList || !categoriasList.length) {
        catListEl.innerHTML = '<div style="padding:32px 16px;text-align:center;color:#9ca3af;font-size:14px;">Nenhuma categoria configurada.</div>';
        return;
      }
      catListEl.innerHTML = '';
      categoriasList.forEach(cat => {
        const prodIds = (cat.produto_ids || []).map(Number);
        const firstProd = produtosData.find(p => prodIds.includes(Number(p.id)));
        const thumbSrc = firstProd ? firstProd.imagemPrincipal : FALLBACK_MEDIA;
        const count = prodIds.filter(id => produtosData.some(p => Number(p.id) === id)).length;
        const item = document.createElement('div');
        item.className = 'cat-list-item';
        item.innerHTML = `<img src="${thumbSrc}" class="cat-list-thumb" onerror="this.src='${FALLBACK_MEDIA}';"><span style="flex:1;font-size:14px;font-weight:600;color:#111;">${cat.nome}</span><span style="font-size:14px;color:#9ca3af;margin-right:4px;">${count}</span><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#9ca3af" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M9 18l6-6-6-6"/></svg>`;
        item.addEventListener('click', () => openCatPanel(cat));
        catListEl.appendChild(item);
      });
    }

    function openCatPanel(cat) {
      const panel = document.getElementById('catPanel');
      const titleEl = document.getElementById('catPanelTitle');
      if (!panel || !titleEl) return;
      titleEl.textContent = cat.nome;
      const prodIds = (cat.produto_ids || []).map(Number);
      catPanelProdutos = produtosData.filter(p => prodIds.includes(Number(p.id)));
      catPanelCurrentFilter = 'recomendados';
      document.querySelectorAll('.cat-filter-btn').forEach(b => {
        b.classList.toggle('active', b.dataset.filter === 'recomendados');
      });
      renderCatPanelGrid();
      panel.classList.add('open');
      document.body.style.overflow = 'hidden';
      history.pushState({catPanel: cat.id}, '', '#cat=' + encodeURIComponent(cat.id));
      // Sync cart badge
      const mainBadge = document.getElementById('quantidade_x');
      const catBadge = document.getElementById('catPanelCartBadge');
      if (mainBadge && catBadge) {
        const n = mainBadge.textContent.trim();
        catBadge.textContent = n;
        catBadge.style.display = (n && n !== '0') ? 'flex' : 'none';
      }
    }

    function closeCatPanel() {
      const panel = document.getElementById('catPanel');
      if (panel) panel.classList.remove('open');
      document.body.style.overflow = '';
      if (location.hash.startsWith('#cat=')) {
        history.pushState(null, '', location.pathname + location.search);
      }
    }

    function renderCatPanelGrid() {
      const grid = document.getElementById('catPanelGrid');
      if (!grid) return;
      let produtos = [...catPanelProdutos];
      if (catPanelCurrentFilter === 'recomendados') produtos.sort((a,b) => ((b.notas||5)*Math.log1p(b.vendidos||0)) - ((a.notas||5)*Math.log1p(a.vendidos||0)));
      else if (catPanelCurrentFilter === 'mais-vendidos') produtos.sort((a,b) => (b.vendidos||0)-(a.vendidos||0));
      else if (catPanelCurrentFilter === 'lancamentos') produtos.sort((a,b) => Number(b.id||0)-Number(a.id||0));
      else if (catPanelCurrentFilter === 'preco') produtos.sort((a,b) => Number(a.preco||0)-Number(b.preco||0));
      grid.innerHTML = '';
      produtos.forEach((produto) => {
        const rating = produto.notas || '5.0';
        const vendidos = produto.vendidos || 0;
        const card = document.createElement('div');
        card.style.cssText = 'background:#fff;padding:10px 8px;display:flex;flex-direction:column;';
        const esgotado = produto.status === 'esgotado';
        const catUrl = urlProduto(produto);
        const pid = produto.id;
        const pct = (()=>{const d=Number(produto.precoComparacao||0)-Number(produto.preco||0);return d>0?Math.round((d/Number(produto.precoComparacao||1))*100):(Math.round(produto.desconto||0));})();
        card.innerHTML = `
          ${esgotado
            ? `<div style="position:relative;width:100%;padding-bottom:100%;margin-bottom:8px;">
                <img src="${produto.imagemPrincipal}" draggable="false" style="position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:#f9f9f9;border-radius:6px;opacity:.45;filter:grayscale(.5);" loading="lazy" onerror="this.onerror=null;this.src='${FALLBACK_MEDIA}';">
                <div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;pointer-events:none;"><span style="background:rgba(0,0,0,.62);color:#fff;font-size:.6rem;font-weight:800;padding:2px 7px;border-radius:4px;text-transform:uppercase;">Esgotado</span></div>
              </div>`
            : `<a href="${catUrl}" data-produto-id="${pid}" class="produto-link" style="position:relative;width:100%;padding-bottom:100%;margin-bottom:8px;display:block;cursor:pointer;">
                <img src="${produto.imagemPrincipal}" draggable="false" onclick="irParaProduto(${pid});return false;" style="position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:#f9f9f9;border-radius:6px;cursor:pointer;" loading="lazy" onerror="this.onerror=null;this.src='${FALLBACK_MEDIA}';">
              </a>`
          }
          <div style="flex:1;display:flex;flex-direction:column;justify-content:space-between;">
            ${esgotado ? `<div>` : `<a href="${catUrl}" data-produto-id="${pid}" class="produto-link" style="display:block;cursor:pointer;">`}
              ${(SHOW_OFICIAL||SHOW_TORCER) ? "<div style='display:flex;align-items:center;gap:4px;margin-bottom:2px;'>" + (SHOW_OFICIAL ? "<img src='/uploads/tagoficial.png' style='height:12px;width:auto;display:block;flex-shrink:0;'>" : '') + (SHOW_TORCER ? "<img src='/uploads/tagtorcer.png' style='height:12px;width:auto;display:block;flex-shrink:0;'>" : '') + "</div>" : ''}
              <div style="font-size:12px;font-weight:600;color:#111;line-height:1.3;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;margin-bottom:5px;">${produto.titulo}</div>
              <div style="display:flex;flex-wrap:nowrap;gap:3px;margin-bottom:4px;overflow:hidden;align-items:center;">
                ${produto.promo_ativa?"<span style='display:inline-flex;align-items:center;border-radius:4px;overflow:hidden;flex-shrink:0;height:15px;background:#e8562a;' class='oferta-badge-wrap'><img src='/uploads/oferta-relamapago.png?v=2' style='height:15px;width:auto;display:block;'><span class='oferta-timer' style='background:#fff0e8;color:#e8562a;font-size:10px;font-weight:800;padding:0 7px;height:100%;display:flex;align-items:center;'>00:20:00</span></span>":""}
                <span style="background:#ffd0d9;color:#d6003a;font-size:9.5px;font-weight:700;padding:0 5px;border-radius:3px;display:inline-flex;align-items:center;gap:2px;white-space:nowrap;flex-shrink:0;height:15px;box-sizing:border-box;"><img src='/uploads/bilhete.png?v=2' width='9' height='9' style='display:block;flex-shrink:0;'/>${pct}% OFF</span>
                <span style="background:#b2f0f5;color:#006875;font-size:9.5px;font-weight:700;padding:0 5px;border-radius:3px;white-space:nowrap;flex-shrink:0;height:15px;box-sizing:border-box;display:inline-flex;align-items:center;">${t('free_shipping')}</span>
              </div>
              <div style="display:flex;align-items:center;gap:3px;margin-bottom:4px;"><span style="color:#f59e0b;font-size:11px;">★</span><span style="font-size:10px;color:#6b7280;">${rating} | ${t('sold_count',{n:vendidos})}</span></div>
            ${esgotado ? '</div>' : '</a>'}
            ${esgotado
              ? `<button disabled style="width:100%;border-radius:6px;background:#e5e7eb;color:#9ca3af;font-size:12px;font-weight:700;padding:7px 0;border:0;cursor:not-allowed;">Esgotado</button>`
              : `<div style="display:flex;align-items:center;justify-content:space-between;margin-top:4px;">
                  <div><div style="font-size:16px;font-weight:700;color:#fe2d55;line-height:1.1;margin-bottom:1px;">R$ ${formatBRL(produto.preco)}</div><div style="font-size:10px;color:#9ca3af;text-decoration:line-through;">R$ ${formatBRL(produto.precoComparacao)}</div></div>
                  <button data-cat-modal style="background:#ffe0e6;border:none;border-radius:50%;width:36px;height:36px;display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;"><img src="/uploads/carrinho-rosa.png?v=3" style="width:28px;height:28px;object-fit:contain;"></button>
                </div>`
            }
          </div>`;
        card.querySelectorAll('[data-cat-modal]').forEach(el => {
          el.addEventListener('click', (e) => { e.preventDefault(); e.stopPropagation(); abrirModalProduto(produto); });
        });
        grid.appendChild(card);
      });
    }

    function showTab(tab) {
      const filterBar = document.getElementById('produtosFilterBar');
      Object.entries(tabPanes).forEach(([key, el]) => {
        if (!el) return;
        if (key === tab) {
          el.classList.remove('hidden');
          el.classList.add('block');
        } else {
          el.classList.add('hidden');
          el.classList.remove('block');
        }
      });
      if (filterBar) {
        filterBar.classList.toggle('hidden', tab !== 'produtos');
      }
    }

    function carregarProdutos() {
      fetch('produtos.json?t=' + Date.now())
        .then(res => res.json())
        .then(data => {
          const arr = Array.isArray(data) ? data : [];
          const normalized = arr.map(normalizarProduto);
          const seenTitles = new Set();
          produtosData = normalized.filter((produto) => {
            const key = String(produto?.titulo || '').trim().toLowerCase();
            if (!key || seenTitles.has(key)) {
              return false;
            }
            seenTitles.add(key);
            return true;
          });
          // Aplica ordenação inicial de preço (descendente por padrão)
          ordenarProdutos();
          renderProdutos();
          renderHomeSections();
          // Carrega categorias da loja
          fetch('loja.json?t=' + Date.now())
            .then(r => r.json())
            .then(loja => { categoriasList = Array.isArray(loja.categorias) ? loja.categorias : []; renderCategoriasTab(); restoreCatFromHash(); })
            .catch(() => { categoriasList = []; renderCategoriasTab(); });
        })
        .catch(error => {
          console.error('Erro ao carregar produtos:', error);
          produtosData = [];
          renderProdutos();
          renderHomeSections();
          renderCategoriasTab();
        });
    }

    document.addEventListener('click', function (e) {
      if (e.target.closest('[data-action="open-modal"], [data-cat-modal], button, [role="button"]')) return;
      var el = e.target.closest('[data-produto-id], a.produto-link');
      if (!el) return;
      var id = el.getAttribute('data-produto-id');
      if (!id && el.href) {
        var m = String(el.href).match(/produto_id=([^&]+)/);
        if (m) id = decodeURIComponent(m[1]);
      }
      if (!id) return;
      e.preventDefault();
      e.stopPropagation();
      irParaProduto(id);
    }, true);

    document.addEventListener('DOMContentLoaded', () => {
      productsContainer = document.getElementById('products');
      precoIconRef = document.getElementById('precoIcon');
      precoBtnRef = document.getElementById('precoBtn');
      tabPanes = {
        inicio: document.getElementById('tab-inicio'),
        produtos: document.getElementById('tab-produtos'),
        categorias: document.getElementById('tab-categorias'),
      };
      document.getElementById('catPanelBack')?.addEventListener('click', closeCatPanel);
      window.addEventListener('popstate', function(e) {
        const panel = document.getElementById('catPanel');
        if (panel && panel.classList.contains('open')) {
          panel.classList.remove('open');
          document.body.style.overflow = '';
        }
      });
      document.querySelectorAll('.cat-filter-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          catPanelCurrentFilter = btn.dataset.filter;
          document.querySelectorAll('.cat-filter-btn').forEach(b => b.classList.toggle('active', b === btn));
          renderCatPanelGrid();
        });
      });
      const homeVerMaisBtn = document.getElementById('homeVerMaisBtn');
      const imageViewer = document.getElementById('imageViewer');
      const imageViewerClose = document.getElementById('imageViewerClose');
      const imageViewerPrev = document.getElementById('imageViewerPrev');
      const imageViewerNext = document.getElementById('imageViewerNext');
      const imageViewerContent = document.getElementById('imageViewerContent');
      const imageViewerBackdrop = document.querySelector('#imageViewer .image-viewer-backdrop');

      imageViewerClose?.addEventListener('click', closeImageViewer);
      imageViewerBackdrop?.addEventListener('click', closeImageViewer);
      imageViewerPrev?.addEventListener('click', () => showImageViewerIndex(galleryIndex - 1));
      imageViewerNext?.addEventListener('click', () => showImageViewerIndex(galleryIndex + 1));

      imageViewerContent?.addEventListener('touchstart', (event) => {
        if (!event.touches || event.touches.length !== 1) return;
        galleryTouchStartX = event.touches[0].clientX;
      }, { passive: true });

      imageViewerContent?.addEventListener('touchend', (event) => {
        if (galleryTouchStartX === null || !event.changedTouches || !event.changedTouches.length) return;
        const endX = event.changedTouches[0].clientX;
        const delta = endX - galleryTouchStartX;
        if (Math.abs(delta) > 40 && galleryImages.length > 1) {
          showImageViewerIndex(galleryIndex + (delta < 0 ? 1 : -1));
        }
        galleryTouchStartX = null;
      });

      document.addEventListener('keydown', (event) => {
        if (!imageViewer || !imageViewer.classList.contains('show')) return;
        if (event.key === 'Escape') closeImageViewer();
        if (event.key === 'ArrowLeft') showImageViewerIndex(galleryIndex - 1);
        if (event.key === 'ArrowRight') showImageViewerIndex(galleryIndex + 1);
      });

      if (precoIconRef) {
        if (precoIconRef) precoIconRef.style.transform = isAsc ? 'rotate(0deg)' : 'rotate(180deg)';
      }

      renderCarrinho();
      carregarProdutos();

      initFreteCountdown();
      updateFreteProgress();

      const freteBtn = document.getElementById('freteResgateBtn');
      if (freteBtn) {
        freteBtn.addEventListener('click', () => {
          const total = getCartTotal();
          if (total < FRETE_META) {
            showCenterToast(t('add_more_for_free_shipping'), 'info', 2000);
            return;
          }
          localStorage.setItem('freteGratisResgatado', '1');
          showCenterToast(t('free_shipping_unlocked'), 'success', 2200);
          updateFreteProgress();
        });
      }

      // Mostra aba padrão
      showTab('produtos');

      document.querySelectorAll('.filter-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          const filtro = btn.getAttribute('data-filter') || 'recomendado';

          if (filtro === 'preco') {
            currentFilter = 'preco';
            ordenarProdutos();
            if (precoIconRef) {
              if (precoIconRef) precoIconRef.style.transform = 'rotate(180deg)';
            }
            document.querySelectorAll('.filter-btn').forEach(el => {
              el.classList.toggle('active', el.getAttribute('data-filter') === 'preco');
            });
            renderProdutos();
            showCenterToast(t('sort_price_desc'), 'info', 1700);
            return;
          }

          currentFilter = filtro;
          document.querySelectorAll('.filter-btn').forEach(el => el.classList.remove('active'));
          btn.classList.add('active');
          renderProdutos();
        });
      });

      // Seguir loja
      const seguirBtn = document.getElementById('seguirBtn');
      if (seguirBtn) {
        const syncSeguir = () => {
          const seguindo = localStorage.getItem('lojaSeguindo') === '1';
          seguirBtn.textContent = seguindo ? t('following') : t('follow');
          if (seguindo) {
            seguirBtn.classList.remove('btn-soft');
            seguirBtn.style.setProperty('background', 'rgba(224, 224, 224, 0.65)', 'important');
            seguirBtn.style.setProperty('color', '#374151', 'important');
            seguirBtn.style.setProperty('border', '1px solid #dcdcdc', 'important');
            seguirBtn.style.borderRadius = '999px';
            seguirBtn.style.boxShadow = '0 1px 4px rgba(0,0,0,0.06)';
            seguirBtn.style.cursor = 'default';
          } else {
            seguirBtn.classList.add('btn-soft');
            seguirBtn.style.setProperty('background', '#e11d48', 'important');
            seguirBtn.style.setProperty('color', '#fff', 'important');
            seguirBtn.style.setProperty('border', 'none', 'important');
            seguirBtn.style.borderRadius = '';
            seguirBtn.style.boxShadow = '';
            seguirBtn.style.cursor = 'pointer';
          }
        };
        syncSeguir();
        seguirBtn.addEventListener('click', () => {
          const seguindo = localStorage.getItem('lojaSeguindo') === '1';
          if (seguindo) return;
          localStorage.setItem('lojaSeguindo', '1');
          showCenterToast(t('now_following'), 'text', 2500);
          syncSeguir();
        });
      }

      // Resgatar cupons
      const cuponsResgatados = new Set(JSON.parse(localStorage.getItem('cuponsResgatados') || '[]'));
      const marcarResgatado = (btn, code) => {
        btn.textContent = t('redeemed');
        btn.disabled = true;
        btn.style.setProperty('background', '#e5e7eb', 'important');
        btn.style.setProperty('color', '#374151', 'important');
        btn.style.setProperty('border', '1px solid #d1d5db', 'important');
        btn.style.cursor = 'default';
      };

      document.querySelectorAll('.resgatar-btn').forEach(btn => {
        const code = btn.dataset.code || btn.getAttribute('aria-label') || 'CUPOM';
        if (cuponsResgatados.has(code)) {
          marcarResgatado(btn, code);
        }
        btn.addEventListener('click', async () => {
          if (btn.disabled) return;
          try {
            if (navigator.clipboard && navigator.clipboard.writeText) {
              await navigator.clipboard.writeText(code);
            } else {
              const temp = document.createElement('textarea');
              temp.value = code;
              temp.style.position = 'fixed';
              temp.style.left = '-9999px';
              document.body.appendChild(temp);
              temp.select();
              document.execCommand('copy');
              temp.remove();
            }
            cuponsResgatados.add(code);
            localStorage.setItem('cuponsResgatados', JSON.stringify(Array.from(cuponsResgatados)));
            marcarResgatado(btn, code);
            showCenterToast(t('coupon_copied', {code: code}), 'success');
          } catch (e) {
            showCenterToast(t('copy_coupon_error'), 'error');
          }
        });
      });

      document.querySelectorAll('.tab-item').forEach(btn => {
        btn.addEventListener('click', () => {
          document.querySelectorAll('.tab-item').forEach(t => t.classList.remove('active'));
          btn.classList.add('active');
          const tab = btn.getAttribute('data-tab') || 'produtos';
          showTab(tab);
        });
      });

      homeVerMaisBtn?.addEventListener('click', () => {
        const prodTabBtn = document.querySelector('.tab-item[data-tab="produtos"]');
        if (prodTabBtn) {
          document.querySelectorAll('.tab-item').forEach(t => t.classList.remove('active'));
          prodTabBtn.classList.add('active');
        }
        showTab('produtos');
        const menuWrapper = document.getElementById('menuWrapper');
        const offset = menuWrapper ? menuWrapper.offsetTop : 0;
        window.scrollTo({ top: offset - 8, behavior: 'smooth' });
      });

      const menuWrapper = document.getElementById('menuWrapper');
      const menuSpacer = document.getElementById('menuSpacer');
      const headerHeight = 120;
      const menuHeight = menuWrapper ? menuWrapper.offsetHeight : 0;
      const searchBar = document.getElementById('searchBar');

      function updateMenuSticky() {
        if (!menuWrapper || !menuSpacer) return;
        const scrollY = window.scrollY;
        const sbH = searchBar ? searchBar.offsetHeight : 0;
        if (scrollY >= headerHeight) {
          menuWrapper.classList.add('fixed-menu', 'bg-white', 'shadow-sm');
          menuWrapper.style.top = sbH + 'px';
          menuSpacer.style.height = `${menuHeight}px`;
          if (searchBar) {
            searchBar.style.background = '#fff';
            searchBar.style.boxShadow = '0 2px 8px rgba(0,0,0,0.08)';
            searchBar.querySelectorAll('svg').forEach(s => s.setAttribute('stroke', '#111'));
            searchBar.querySelectorAll('img').forEach(i => i.style.filter = 'invert(1)');
            const hn = document.getElementById('headerStoreName');
            const ln = document.getElementById('loja-nome');
            if (hn && ln) { hn.textContent = ln.textContent; hn.style.opacity = '1'; }
          }
        } else {
          menuWrapper.classList.remove('fixed-menu', 'shadow-sm');
          menuWrapper.style.top = '';
          menuSpacer.style.height = '0px';
          if (searchBar) {
            searchBar.style.background = 'transparent';
            searchBar.style.boxShadow = 'none';
            searchBar.querySelectorAll('svg').forEach(s => s.setAttribute('stroke', 'white'));
            searchBar.querySelectorAll('img').forEach(i => i.style.filter = '');
            const hn = document.getElementById('headerStoreName');
            if (hn) hn.style.opacity = '0';
          }
        }
      }

      window.addEventListener('scroll', updateMenuSticky);

      const buttonReturn = document.getElementById('button-return');
      if (buttonReturn) {
        buttonReturn.addEventListener('click', () => {
          const qrPixText = window.qrPixText || '';
          if (qrPixText) {
            navigator.clipboard.writeText(qrPixText).then(() => {
              buttonReturn.innerText = t('pix_copied');
              setTimeout(() => {
                buttonReturn.innerText = t('copy_pix');
              }, 2000);
            }).catch(() => {
              alert(t('pix_copy_error'));
            });
          } else {
            alert(t('pix_unavailable'));
          }
        });
      }
    });
  </script>
