<script>
function abrirModalOficial() {
  const m = document.getElementById('modalOficial');
  m.style.display = 'flex';
  document.body.style.overflow = 'hidden';
}
function fecharModalOficial() {
  const m = document.getElementById('modalOficial');
  m.style.display = 'none';
  document.body.style.overflow = '';
}
function fecharModalOficialBg(e) {
  if (e.target === document.getElementById('modalOficial')) fecharModalOficial();
}
// Extração de cor dominante do logo para colorir o banner
function aplicarCorLogo(imgEl) {
  try {
    const canvas = document.createElement('canvas');
    canvas.width = 20; canvas.height = 20;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(imgEl, 0, 0, 20, 20);
    const d = ctx.getImageData(0, 0, 20, 20).data;
    let r=0,g=0,b=0,n=0;
    for (let i=0;i<d.length;i+=4) {
      const a=d[i+3],pr=d[i],pg=d[i+1],pb=d[i+2];
      if (a<128) continue;
      // ignora pixels brancos/cinzas (baixa saturação)
      if (Math.max(pr,pg,pb)-Math.min(pr,pg,pb)<40) continue;
      r+=pr; g+=pg; b+=pb; n++;
    }
    if (!n) {
      const hw = document.getElementById('heroWrap');
      if (hw) hw.style.opacity = '1';
      return;
    }
    r=Math.round(r/n); g=Math.round(g/n); b=Math.round(b/n);
    const cl = (v, mn) => Math.min(255, Math.max(mn, Math.round(v)));
    const dark  = `rgb(${cl(r*0.38,15)},${cl(g*0.38,22)},${cl(b*0.38,16)})`;
    const mid   = `rgb(${cl(r*0.58,28)},${cl(g*0.58,42)},${cl(b*0.58,30)})`;
    const light = `rgb(${cl(r*0.78,44)},${cl(g*0.78,65)},${cl(b*0.78,48)})`;
    const heroWrap = document.getElementById('heroWrap');
    if (heroWrap) {
      heroWrap.style.background = `linear-gradient(to bottom, ${dark} 0%, ${mid} 20%, ${light} 50%, rgba(255,255,255,0.70) 78%, rgba(255,255,255,0) 100%)`;
    }
    const avatarWrap2 = document.getElementById('loja-avatar-wrap');
    if (avatarWrap2) avatarWrap2.style.background = mid;
    const hwShow = document.getElementById('heroWrap');
    if (hwShow) hwShow.style.opacity = '1';
  } catch(e) {}
}
document.addEventListener('DOMContentLoaded', function() {
  setTimeout(() => { const hw=document.getElementById('heroWrap'); if(hw && hw.style.opacity==='0') hw.style.opacity='1'; }, 600);
  const logo = document.getElementById('loja-logo');
  if (!logo) return;
  const tryExtract = () => {
    if (logo.complete && logo.naturalWidth > 1) {
      aplicarCorLogo(logo);
    } else {
      logo.addEventListener('load', function onLoad() {
        logo.removeEventListener('load', onLoad);
        // Pequeno delay para garantir render cross-origin
        setTimeout(() => aplicarCorLogo(logo), 100);
      });
    }
  };
  // Re-checar quando o logo for trocado (carregarLoja altera o src)
  const orig = Object.getOwnPropertyDescriptor(HTMLImageElement.prototype, 'src');
  if (logo.src && logo.src !== '' && !logo.src.includes('data:image/gif')) {
    tryExtract();
  } else {
    const obs = new MutationObserver(() => { setTimeout(tryExtract, 200); });
    obs.observe(logo, {attributes:true, attributeFilter:['src']});
  }
});
function resgatarCupom(code, btn) {
  const resgatados = new Set(JSON.parse(localStorage.getItem('cuponsResgatados') || '[]'));
  if (resgatados.has(code)) return;
  resgatados.add(code);
  localStorage.setItem('cuponsResgatados', JSON.stringify(Array.from(resgatados)));
  if (btn) _marcarCupomResgatado(btn);
  const toast = document.createElement('div');
  toast.className = 'toast-center show';
  toast.innerHTML = '<div class="toast-icon success"><svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg></div><div class="toast-text">Cupom ' + code + ' resgatado!</div>';
  document.body.appendChild(toast);
  setTimeout(() => { toast.classList.remove('show'); setTimeout(() => toast.remove(), 300); }, 2200);
}
function _marcarCupomResgatado(btn) {
  btn.textContent = 'Resgatado';
  btn.disabled = true;
  btn.style.background = '#9ca3af';
  btn.style.cursor = 'default';
  btn.style.opacity = '0.75';
}
// Restaura estado dos cupons já resgatados ao carregar
(function() {
  const resgatados = new Set(JSON.parse(localStorage.getItem('cuponsResgatados') || '[]'));
  document.querySelectorAll('button[data-code]').forEach(btn => {
    if (resgatados.has(btn.dataset.code)) _marcarCupomResgatado(btn);
  });
})();
</script>

